CREATE TABLE IF NOT EXISTS settings (key TEXT PRIMARY KEY, value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS baseline (path TEXT PRIMARY KEY, revision INTEGER NOT NULL, sha TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS pending (slot INTEGER PRIMARY KEY, path TEXT NOT NULL, expected INTEGER NOT NULL, operation TEXT NOT NULL, bytes BLOB NOT NULL);
CREATE TABLE IF NOT EXISTS conflicts (path TEXT PRIMARY KEY, local TEXT NOT NULL, remote TEXT NOT NULL, revision INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS incoming (slot INTEGER PRIMARY KEY, path TEXT NOT NULL, revision INTEGER NOT NULL, sha TEXT NOT NULL);
